import type { DimensionsM } from '../domain/dimensions';

/**
 * Pre-built models of popular furniture. Each is our own generic design whose overall size
 * matches a well-known retail product's published dimensions. The product is named only to
 * describe the size; the model is not that product.
 * Models are generated by blender/make_products.py into public/models/products/.
 */
/** One colour choice, named as the retailer names it. Hex values are visual approximations. */
export type ColorOption = {
  name: string;
  hex: string;
  /** Surface roughness 0 (gloss) to 1 (matte). Defaults to the model's own. */
  roughness?: number;
  /** Different colours for specific materials, for two-tone finishes. */
  overrides?: Record<string, string>;
};

/** A recolourable part of a model, e.g. the frame or the cushion. */
export type ColorPart = {
  label: string;
  /** glTF material names in the model that take this part's colour. */
  materials: string[];
  /** The first option matches the model file's built-in colour. */
  options: ColorOption[];
};

export const BRANDS = ['IKEA', 'Article', 'West Elm', 'Structube'] as const;
export type Brand = (typeof BRANDS)[number];

import { FURNITURE_TYPES, MY_FURNITURE, type FurnitureType } from '../catalog/furnitureTypes';
export { FURNITURE_TYPES, MY_FURNITURE, type FurnitureType };

export type Product = {
  id: string;
  label: string;
  /** The company whose product this model is sized like. */
  brand: Brand | typeof MY_FURNITURE;
  type: FurnitureType;
  /** Which retail product this model is sized like. */
  sizedLike: string;
  /** Where the dimensions were taken from. */
  sourceUrl: string;
  size: DimensionsM;
  colorParts: ColorPart[];
  glbUrl: string;
  /** Present for furniture the user built from their own photos. */
  custom?: { createdAt: string; notes: string };
};

const cm = (width: number, depth: number, height: number): DimensionsM => ({
  width: width / 100,
  depth: depth / 100,
  height: height / 100,
});
const inches = (width: number, depth: number, height: number) => cm(width * 2.54, depth * 2.54, height * 2.54);

