export const PRODUCTS: Product[] = RAW.map((p) => ({ ...p, glbUrl: glb(p.id) }));

// ---------- Furniture the user added from photos (loaded from the scan server) ----------

let customProducts: Product[] = [];

export function setCustomProducts(list: Product[]) {
  customProducts = list;
}

/** User-added furniture first, then the built-in catalogue. */
export function allProducts(): Product[] {
  return [...customProducts, ...PRODUCTS];
}

export function getProduct(id: string): Product | undefined {
  return allProducts().find((p) => p.id === id);
}

export type ColorChoices = Record<string, number>; // part label -> option index

/** Map each material name to the colour chosen for its part (two-tone overrides included). */
export function resolveColors(
  product: Product,
  choices: ColorChoices,
): Record<string, { hex: string; roughness?: number }> {
  const out: Record<string, { hex: string; roughness?: number }> = {};
  for (const part of product.colorParts) {
    const option = part.options[choices[part.label] ?? 0] ?? part.options[0];
    for (const material of part.materials) {
      out[material] = { hex: option.overrides?.[material] ?? option.hex, roughness: option.roughness };
    }
  }
  return out;
}

/** Human-readable summary of the chosen colours, e.g. "Black-brown / Knisa black". */
export function describeColors(product: Product, choices: ColorChoices): string {
  return product.colorParts.map((p) => (p.options[choices[p.label] ?? 0] ?? p.options[0]).name).join(' / ');
}

export type ProductFilter = { brand?: string; type?: string; query?: string };

/** Lowercase and strip accents so "poang" finds "POÄNG". */
const fold = (text: string) => text.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

/**
 * Filter by brand and furniture type, then by a free-text search. Every word in the query must
 * appear somewhere in the product's name, the product it is sized like, brand, type or colours.
 */
export function filterProducts(products: Product[], filter: ProductFilter): Product[] {
  const words = fold(filter.query ?? '').split(/\s+/).filter(Boolean);
  return products.filter((p) => {
    if (filter.brand && p.brand !== filter.brand) return false;
    if (filter.type && p.type !== filter.type) return false;
    if (!words.length) return true;
    const haystack = fold(
      [p.label, p.sizedLike, p.brand, p.type, ...p.colorParts.flatMap((c) => c.options.map((o) => o.name))].join(' '),
    );
    return words.every((w) => haystack.includes(w));
  });
}
